memberdef.initializer:
do { \
		if ((UseCount) < 255U) { \
			(UseCount)++; \
		} else { \
			PmInfo("Usecount is already 255, Clk: 0x%x (%s)\r\n", (NodeId), (Name)); \
		} \
	} while (0)

do { \
		if ((UseCount) > 0) { \
			(UseCount)--; \
		} else { \
			PmWarn("Usecount is already 0, Clk: 0x%x (%s)\r\n", (NodeId), (Name)); \
		} \
	} while (0)
